const DEMO_QR_KEY = 'medidesk_demo_qr_passes';
const demoQrStore = () => JSON.parse(localStorage.getItem(DEMO_QR_KEY) || '{}');
const saveDemoQrStore = store => localStorage.setItem(DEMO_QR_KEY, JSON.stringify(store));
async function createDemoQrPass(appointment) {
  const expiresAt = Date.now() + 24 * 60 * 60 * 1000;
  const nonce = crypto.randomUUID();
  const token = `mdqr.demo.v1.${appointment.id}.${expiresAt}.${nonce}`;
  const image = await QRCode.toDataURL(token, { width: 260, margin: 2, color: { dark: '#10233f', light: '#ffffff' } });
  const pass = { token, image, expiresAt, appointmentId: appointment.id, used: false };
  const store = demoQrStore(); store[appointment.id] = pass; saveDemoQrStore(store);
  return pass;
}
function getDemoQrPass(id) { return demoQrStore()[id]; }

