function App() {
  const [user, setUser] = useState(null);
  const [checkingSession, setCheckingSession] = useState(true);
  const [toast, setToast] = useState(null);
  useEffect(() => { const removeBadge = () => document.getElementById('nl-badge')?.remove(); removeBadge(); const observer = new MutationObserver(removeBadge); observer.observe(document.body, { childList: true, subtree: true }); return () => observer.disconnect(); }, []);
  useEffect(() => { const token = localStorage.getItem('medidesk_token'); if (!token) return setCheckingSession(false); if (token.startsWith('demo-client:')) { try { const saved = JSON.parse(localStorage.getItem('medidesk_user') || 'null'); if (saved) { setUser(saved); setCheckingSession(false); return; } } catch {} } API.get('/auth/me').then(({ data }) => setUser(data.user)).catch(() => { localStorage.removeItem('medidesk_token'); localStorage.removeItem('medidesk_user'); }).finally(() => setCheckingSession(false)); }, []);
  const login = (profile, token) => { localStorage.setItem('medidesk_token', token); localStorage.setItem('medidesk_user', JSON.stringify(profile)); setUser(profile); };
  const logout = () => { localStorage.removeItem('medidesk_token'); localStorage.removeItem('medidesk_user'); setUser(null); };
  const notify = (message, kind = 'success') => { setToast({ message, kind }); window.setTimeout(() => setToast(null), 3200); };
  if (checkingSession) return <div className="session-loading">Checking secure MediDesk session…</div>;
  return <>
    <Routes>
      <Route path="/" element={<Home user={user} />} />
      <Route path="/login" element={<Login onLogin={login} notify={notify} />} />
      <Route path="/register" element={<Register onLogin={login} notify={notify} />} />
      <Route path="/forgot-password" element={<ForgotPassword notify={notify} />} />
      <Route path="/reset-password/:token" element={<ResetPassword notify={notify} />} />
      <Route path="/about" element={<About />} />
      <Route path="/contact" element={<Contact notify={notify} />} />
      <Route path="/unauthorized" element={<Unauthorized />} />
      <Route path="/dashboard" element={<Protected user={user}><Dashboard user={user} notify={notify} /></Protected>} />
      <Route path="/appointments" element={<Protected user={user}><Appointments user={user} notify={notify} /></Protected>} />
      <Route path="/records" element={<Protected user={user}><Records user={user} notify={notify} /></Protected>} />
      <Route path="/profile" element={<Protected user={user}><Profile user={user} setUser={login} notify={notify} /></Protected>} />
      <Route path="*" element={<NotFound />} />
    </Routes>
    {toast && <div className={`toast ${toast.kind}`}><Check size={16} />{toast.message}</div>}
    <CareAssistant user={user} />
  </>;
}

function CareAssistant({ user }) {
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);
  const [draft, setDraft] = useState('');
  const [messages, setMessages] = useState([{ from: 'ai', text: `Hi${user?.name ? ` ${user.name.split(' ')[0]}` : ''}! I can navigate MediDesk, book an appointment, find a clinic, or show a secure check-in pass.` }]);
  const reply = text => {
    const normalized = text.toLowerCase();
    let answer = 'I can take you to Appointments, Medical records, Profile, Dashboard, or help find a clinic. Try “show my records” or “open profile.”';
    let path;
    if (normalized.includes('record') || normalized.includes('prescription') || normalized.includes('report')) { answer = 'Opening your medical records and prescriptions.'; path = '/records'; }
    else if (normalized.includes('profile') || normalized.includes('account')) { answer = 'Opening your profile and security settings.'; path = '/profile'; }
    else if (normalized.includes('dashboard') || normalized.includes('home')) { answer = 'Opening your role workspace overview.'; path = '/dashboard'; }
    else if (normalized.includes('book') || normalized.includes('appointment') || normalized.includes('schedule')) { answer = 'Opening Appointments so you can choose a doctor, date, time, and reason.'; path = '/appointments?book=1'; }
    else if (normalized.includes('clinic') || normalized.includes('near') || normalized.includes('find')) answer = 'For this demo: Northline Health · 1.2 mi, Riverside Family Clinic · 2.4 mi, and Harborview Medical · 3.1 mi. I can also take you to Appointments.';
    else if (normalized.includes('check') || normalized.includes('qr') || normalized.includes('scan')) { answer = user?.role === 'Doctor' || user?.role === 'Admin' ? 'Opening the secure patient check-in station.' : 'Open an appointment’s Details card to display its secure QR check-in pass.'; path = user?.role === 'Doctor' || user?.role === 'Admin' ? '/dashboard' : '/appointments'; }
    else if (normalized.includes('symptom') || normalized.includes('pain') || normalized.includes('fever') || normalized.includes('cough') || normalized.includes('rash')) answer = 'I can record symptoms for a clinician, but I cannot diagnose. Open an appointment and include the details. For severe or urgent symptoms, contact local emergency services.';
    setMessages(current => [...current, { from: 'user', text }, { from: 'ai', text: answer }]);
    if (path) window.setTimeout(() => navigate(path), 400);
  };
  const send = e => { e.preventDefault(); if (!draft.trim()) return; const text = draft.trim(); setDraft(''); reply(text); };
  const quick = text => reply(text);
  return <div className="assistant-wrap"><button className="assistant-launch" onClick={() => setOpen(!open)} aria-label="Open Clara"><Sparkles size={19} /><span>Clara</span></button>{open && <section className="assistant-panel" aria-label="Clara navigation assistant"><div className="assistant-head"><div><span className="assistant-icon"><Bot size={17} /></span><span><strong>Clara</strong><small>Secure navigation · ready to help</small></span></div><button onClick={() => setOpen(false)} aria-label="Close assistant"><X size={17} /></button></div><div className="assistant-messages">{messages.map((message, index) => <div key={`${message.from}-${index}`} className={`assistant-message ${message.from}`}>{message.from === 'ai' && <Bot size={14} />}{message.text}</div>)}</div><div className="assistant-quick"><button onClick={() => quick('Open appointments')}><CalendarDays size={13} /> Appointments</button><button onClick={() => quick('Show my records')}><FileText size={13} /> Records</button><button onClick={() => quick('Open profile')}><UserRound size={13} /> Profile</button><button onClick={() => quick('Find a clinic near me')}><MapPin size={13} /> Find a clinic</button></div><form className="assistant-form" onSubmit={send}><input value={draft} onChange={e => setDraft(e.target.value)} placeholder="Ask where to go..." aria-label="Ask Clara" /><button type="submit" aria-label="Send message"><Send size={15} /></button></form></section>}</div>;
}
